#include <iostream>

bool isPrime(int n)
{
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i)
        if (n % i == 0) return false;
    return true;
}

int main()
{
    int a{}, b{};
    if (!(std::cin >> a >> b)) return 0;

    int count{};
    int largest{};
    bool found{ false };

    for (int n = a; n <= b; ++n)
    {
        if (isPrime(n))
        {
            ++count;
            largest = n;
            found = true;
        }
    }

    std::cout << "count " << count << "\n";
    if (found) std::cout << "largest " << largest << "\n";
    else       std::cout << "largest none\n";

    return 0;
}
